const FLOWS = new Set(['work', 'ask']);
const interruptedFlow = (layout) => layout?.work ? 'work' : layout?.ask ? 'ask' : null;

/** Retain an interrupted pack flow through carrying, falling and the complete landing/recovery. */
export function withActionRecovery(body) {
  let pending = null, disposed = false;
  const overrides = {
    set(state) {
      if ('matterActivity' in state) pending = null;
      return body.set?.(state);
    },
    step(dt) {
      if (disposed) return;
      // No autonomous decision may slip into the frame that finishes landing.
      if (pending) body.set?.({ hold: 0.2 });
      body.step(dt);
      if (!(dt > 0 && Number.isFinite(dt)) || !pending) return;
      const layout = body.layout();
      if (layout.mode !== 'idle' || layout.busy || layout.pressing || interruptedFlow(layout)) return;
      if (body.do(pending) !== false) pending = null;
    },
    do(word) {
      if (pending && FLOWS.has(word)) { pending = word; return true; }
      pending = null;
      const layout = body.layout();
      if (FLOWS.has(word) && (layout.busy || layout.pressing || ['land', 'dizzy', 'wake'].includes(layout.mode))) {
        pending = word;
        return true;
      }
      return body.do(word);
    },
    layout() { return { ...body.layout(), recovering: pending }; },
    dispose() { disposed = true; pending = null; return body.dispose?.(); },
  };
  if (body.pointer) overrides.pointer = (type, point) => {
    const layout = body.layout();
    const flow = !layout.matterActivity && interruptedFlow(layout);
    const result = body.pointer(type, point);
    if (type === 'down' && body.layout().pressing && flow) pending = flow;
    return result;
  };
  if (body.drop) overrides.drop = (point) => {
    if (!body.layout().matterActivity) pending ??= interruptedFlow(body.layout());
    return body.drop(point);
  };
  const bound = new Map();
  return new Proxy(body, {
    get(target, key) {
      if (Object.hasOwn(overrides, key)) return overrides[key];
      const value = Reflect.get(target, key, target);
      if (typeof value !== 'function') return value;
      if (!bound.has(key)) bound.set(key, (...args) => {
        if (key === 'walk' || key === 'move' || key === 'stopWalk') pending = null;
        return value.apply(target, args);
      });
      return bound.get(key);
    },
  });
}
